/* Quais status da Base são cancelamento — perguntando a ela, não cravando id.

   Os ids mudam de conta para conta e ninguém lembra de vir aqui no dia em
   que mudarem. E há mais de um: no painel aparecem "Cancelado", "Cancelado
   com Devolução" e "Cancelado com NF". Os dois primeiros vão para a lista
   Cancelados; o terceiro tem fila própria porque envolve estorno de nota. */
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Não consegui ler os status da Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const lista = Array.isArray(r.statuses) ? r.statuses
            : Object.entries(r.statuses || {}).map(([id, v]) => ({ id, name: (v && v.name) || String(v) }));

const comNF = [], simples = [];
lista.forEach(s => {
  const nome = String(s.name || '');
  if (!/cancel/i.test(nome)) return;
  /* "com NF" e "nota fiscal" são a mesma coisa escrita de dois jeitos; a
     leitura é pelo texto porque é o texto que a operação lê no painel. */
  if (/\bnf\b|nota\s*fiscal/i.test(nome)) comNF.push({ id: String(s.id), nome });
  else simples.push({ id: String(s.id), nome });
});

if (!comNF.length && !simples.length) {
  throw new Error('Nenhum status com "cancel" no nome. Status existentes: '
    + lista.map(s => s.id + '=' + s.name).join(' | '));
}
console.log('cancelamento simples: ' + (simples.map(s => s.nome).join(', ') || '—')
  + ' | com NF: ' + (comNF.map(s => s.nome).join(', ') || '—'));

return [{ json: { comNF, simples, desde: '2026-01-01' } }];

/* Monta as duas listas a partir dos pedidos da Base.

   O filtro de status é feito AQUI e não na chamada: o filter_order_status_id
   da BaseLinker é ignorado em silêncio — devolve pedidos de outro status
   como se tivesse funcionado. Foi medido em 22/08/2026 e é o motivo de
   este fluxo ler tudo e separar depois.

   O que já existe no LiveOps não é recriado: o registro guarda o número do
   pedido, e é por ele que a comparação acontece. Sem isso, cada rodada
   criaria de novo a mesma solicitação e a fila do dia viraria uma pilha de
   duplicatas. */
const cfg = $('Quais status são cancelamento').first().json;
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('A Base recusou a leitura de pedidos: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const pedidos = r.orders || [];

const jaTem = $('O que já está no LiveOps').first().json || {};
const numeros = new Set();
['canceladas', 'canceladasNF'].forEach(k => {
  Object.values((jaTem && jaTem[k]) || {}).forEach(v => {
    if (v && v.pedidoBase) numeros.add(String(v.pedidoBase));
  });
});

const idsNF = new Set(cfg.comNF.map(s => s.id));
const idsSimples = new Set(cfg.simples.map(s => s.id));
const nomePorId = {};
cfg.comNF.concat(cfg.simples).forEach(s => { nomePorId[s.id] = s.nome; });

/* Nome de canal legível. O order_source vem como "personal", "shop",
   "melibr"… — código de máquina que ninguém reconhece na tela. */
const CANAL = {
  personal: 'WHATSAPP', shop: 'LOJA INTEGRADA', melibr: 'MERCADO LIVRE',
  shopeebr: 'SHOPEE', magalu: 'MAGALU', omnik: 'WHATSAPP'
};

const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const saida = { canceladas: {}, canceladasNF: {} };
let novos = 0, repetidos = 0, foraDoAno = 0;

pedidos.forEach(p => {
  const idStatus = String(p.order_status_id);
  const ehNF = idsNF.has(idStatus);
  const ehSimples = idsSimples.has(idStatus);
  if (!ehNF && !ehSimples) return;

  const quando = new Date((Number(p.date_add) || 0) * 1000);
  const ano = quando.getFullYear();
  /* Só de 2026 em diante, como a tela mostra. Trazer 2025 encheria a fila de
     coisa que ninguém vai tratar. */
  if (ano < 2026) { foraDoAno++; return; }

  const numero = String(p.order_id);
  if (numeros.has(numero)) { repetidos++; return; }

  const dois = n => String(n).padStart(2, '0');
  const iso = quando.getFullYear() + '-' + dois(quando.getMonth() + 1) + '-' + dois(quando.getDate());
  const br = dois(quando.getDate()) + '/' + dois(quando.getMonth() + 1) + '/' + quando.getFullYear()
    + ', ' + dois(quando.getHours()) + ':' + dois(quando.getMinutes());

  const chave = (ehNF ? 'cancnf_' : 'canc_') + numero;
  const registro = {
    id: chave,
    cliente: p.delivery_fullname || p.invoice_fullname || p.user_login || '',
    cpf: String(p.invoice_nip || '').replace(/\D/g, ''),
    telefone: String(p.phone || '').replace(/\D/g, ''),
    plataforma: CANAL[String(p.order_source || '')] || String(p.order_source || '').toUpperCase(),
    pedidoBase: numero,
    dataPedido: iso,
    statusBase: nomePorId[idStatus] || ('status ' + idStatus),
    status: 'aberta',
    criadoEm: br,
    criadoPor: 'Base',
    ordemManual: quando.getTime(),
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };
  saida[ehNF ? 'canceladasNF' : 'canceladas'][chave] = registro;
  novos++;
});

console.log(novos + ' novo(s) — ' + Object.keys(saida.canceladas).length + ' cancelados, '
  + Object.keys(saida.canceladasNF).length + ' com NF | ' + repetidos + ' já existiam | '
  + foraDoAno + ' de antes de 2026 ignorados');

if (!novos) return [];
return [{ json: saida }];
